CREATE OR REPLACE VIEW {{database}}.aml_wallet_risk_assessments_current AS SELECT network_id,assessment_id,data.1 AS subject_id,data.2 AS policy_version,data.3 AS risk_score,data.4 AS risk_level,data.5 AS probability_claimed,data.6 AS signal_count,data.7 AS exposure_run_id,data.8 AS limitations,data.9 AS as_of_block,data.10 AS source_revision,data.11 AS revision,data.12 AS created_at_unix_ms,data.13 AS top_reasons,data.14 AS evidence_refs,data.15 AS as_of_unix_ms,data.16 AS scoring_method,data.17 AS evidence_json,data.18 AS raw_evidence_json FROM (SELECT network_id,assessment_id,argMax(tuple(subject_id,policy_version,risk_score,risk_level,probability_claimed,signal_count,exposure_run_id,limitations,as_of_block,source_revision,revision,created_at_unix_ms,top_reasons,evidence_refs,as_of_unix_ms,scoring_method,evidence_json,raw_evidence_json),revision) AS data FROM {{database}}.aml_wallet_risk_assessments GROUP BY network_id,assessment_id);

CREATE OR REPLACE VIEW {{database}}.aml_wallet_risk_signals_current AS SELECT network_id,assessment_id,signal_id,data.1 AS subject_id,data.2 AS policy_version,data.3 AS signal_type,data.4 AS contribution,data.5 AS summary,data.6 AS evidence_refs,data.7 AS evidence_json,data.8 AS as_of_block,data.9 AS source_revision,data.10 AS revision,data.11 AS created_at_unix_ms,data.12 AS signal_strength,data.13 AS as_of_unix_ms,data.14 AS raw_evidence_json FROM (SELECT network_id,assessment_id,signal_id,argMax(tuple(subject_id,policy_version,signal_type,contribution,summary,evidence_refs,evidence_json,as_of_block,source_revision,revision,created_at_unix_ms,signal_strength,as_of_unix_ms,raw_evidence_json),revision) AS data FROM {{database}}.aml_wallet_risk_signals GROUP BY network_id,assessment_id,signal_id);

CREATE OR REPLACE VIEW {{database}}.aml_asset_metadata_current AS SELECT network_id,asset_id,data.1 AS symbol,data.2 AS name,data.3 AS decimals,data.4 AS asset_standard,data.5 AS source_id,data.6 AS source_reference,data.7 AS review_status,data.8 AS reviewed_by,data.9 AS evidence_refs,data.10 AS revision,data.11 AS created_at_unix_ms,data.12 AS total_supply_raw,data.13 AS code_hash,data.14 AS is_verified,data.15 AS metadata_status,data.16 AS observed_block,data.17 AS verified_at_unix_ms,data.18 AS reviewed_at_unix_ms,data.19 AS updated_at_unix_ms,data.20 AS raw_evidence_json,data.21 AS source_revision,data.22 AS observed_block_hash FROM (SELECT network_id,asset_id,argMax(tuple(symbol,name,decimals,asset_standard,source_id,source_reference,review_status,reviewed_by,evidence_refs,revision,created_at_unix_ms,total_supply_raw,code_hash,is_verified,metadata_status,observed_block,verified_at_unix_ms,reviewed_at_unix_ms,updated_at_unix_ms,raw_evidence_json,source_revision,observed_block_hash),revision) AS data FROM {{database}}.aml_asset_metadata GROUP BY network_id,asset_id);

CREATE OR REPLACE VIEW {{database}}.aml_metadata_jobs_current AS SELECT network_id,job_id,data.1 AS asset_id,data.2 AS status,data.3 AS attempts,data.4 AS next_attempt_unix_ms,data.5 AS last_error,data.6 AS revision,data.7 AS created_at_unix_ms,data.8 AS discovery_id,data.9 AS discovered_block,data.10 AS source_revision,data.11 AS last_error_class,data.12 AS started_at_unix_ms,data.13 AS completed_at_unix_ms,data.14 AS updated_at_unix_ms,data.15 AS raw_evidence_json FROM (SELECT network_id,job_id,argMax(tuple(asset_id,status,attempts,next_attempt_unix_ms,last_error,revision,created_at_unix_ms,discovery_id,discovered_block,source_revision,last_error_class,started_at_unix_ms,completed_at_unix_ms,updated_at_unix_ms,raw_evidence_json),revision) AS data FROM {{database}}.aml_metadata_jobs GROUP BY network_id,job_id);

CREATE OR REPLACE VIEW {{database}}.aml_analysis_publications_visible AS SELECT p.network_id AS network_id, p.family AS family, p.publication_id AS publication_id, p.source_revision AS source_revision, p.as_of_block AS as_of_block, p.block_hash AS block_hash, p.output_revision AS output_revision, p.status AS status, p.row_counts_json AS row_counts_json, p.revision AS revision, p.created_at_unix_ms AS created_at_unix_ms FROM {{database}}.aml_analysis_publications_current AS p INNER JOIN {{database}}.aml_sync_state_current AS s ON p.network_id=s.network_id AND p.source_revision=s.revision INNER JOIN {{database}}.aml_ingested_blocks_canonical AS b ON p.network_id=b.network_id AND p.as_of_block=b.block_number AND p.block_hash=b.block_hash WHERE p.status='complete' AND s.initialized=1 AND p.as_of_block<=s.last_block_number;

CREATE OR REPLACE VIEW {{database}}.aml_cluster_runs_visible AS SELECT f.network_id AS network_id, f.run_id AS run_id, f.status AS status, f.as_of_block AS as_of_block, f.source_revision AS source_revision, f.detector_version AS detector_version, f.cursor_json AS cursor_json, f.started_at_unix_ms AS started_at_unix_ms, f.completed_at_unix_ms AS completed_at_unix_ms, f.truncated AS truncated, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.entity_memberships AS entity_memberships, f.control_claims AS control_claims, f.error_message AS error_message, f.settings_json AS settings_json, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_cluster_runs_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.run_id=p.publication_id AND f.revision=p.output_revision WHERE p.family='cluster' AND f.status='complete' AND f.truncated=0 AND f.source_revision=p.source_revision AND f.as_of_block=p.as_of_block;

CREATE OR REPLACE VIEW {{database}}.aml_cluster_claims_visible AS SELECT f.network_id AS network_id, f.claim_id AS claim_id, f.cluster_id AS cluster_id, f.subject_id AS subject_id, f.heuristic AS heuristic, f.detector_version AS detector_version, f.confidence AS confidence, f.review_status AS review_status, f.source_id AS source_id, f.evidence_refs AS evidence_refs, f.evidence_json AS evidence_json, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.left_subject_id AS left_subject_id, f.right_subject_id AS right_subject_id, f.same_entity AS same_entity, f.run_id AS run_id, f.source_record_id AS source_record_id, f.supersedes_claim_id AS supersedes_claim_id, f.created_by AS created_by, f.reviewed_by AS reviewed_by, f.review_id AS review_id, f.cluster_type AS cluster_type, f.address_role AS address_role, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_cluster_claims_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.run_id=p.publication_id AND f.revision=p.output_revision INNER JOIN {{database}}.aml_cluster_runs_visible AS a ON f.network_id=a.network_id AND f.run_id=a.run_id AND f.revision=a.revision WHERE p.family='cluster';

CREATE OR REPLACE VIEW {{database}}.aml_cluster_memberships_visible AS SELECT f.network_id AS network_id, f.cluster_id AS cluster_id, f.cluster_version AS cluster_version, f.subject_id AS subject_id, f.claim_id AS claim_id, f.status AS status, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.membership_id AS membership_id, f.run_id AS run_id, f.entity_id AS entity_id, f.membership_type AS membership_type, f.confidence AS confidence, f.review_id AS review_id, f.cluster_type AS cluster_type, f.address_role AS address_role, f.evidence_json AS evidence_json, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_cluster_memberships_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.run_id=p.publication_id AND f.revision=p.output_revision INNER JOIN {{database}}.aml_cluster_runs_visible AS a ON f.network_id=a.network_id AND f.run_id=a.run_id AND f.revision=a.revision WHERE p.family='cluster';

CREATE OR REPLACE VIEW {{database}}.aml_cluster_versions_visible AS SELECT f.network_id AS network_id, f.cluster_id AS cluster_id, f.cluster_version AS cluster_version, f.cluster_type AS cluster_type, f.display_name AS display_name, f.change_type AS change_type, f.change_reason AS change_reason, f.source_claim_ids AS source_claim_ids, f.active_member_count AS active_member_count, f.created_by AS created_by, f.evidence_refs AS evidence_refs, f.raw_evidence_json AS raw_evidence_json, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.run_id AS run_id FROM {{database}}.aml_cluster_versions_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.run_id=p.publication_id AND f.revision=p.output_revision INNER JOIN {{database}}.aml_cluster_runs_visible AS a ON f.network_id=a.network_id AND f.run_id=a.run_id AND f.revision=a.revision WHERE p.family='cluster';

CREATE OR REPLACE VIEW {{database}}.aml_exposure_runs_visible AS SELECT f.network_id AS network_id, f.run_id AS run_id, f.seed_id AS seed_id, f.status AS status, f.as_of_block AS as_of_block, f.source_revision AS source_revision, f.policy_version AS policy_version, f.max_hops AS max_hops, f.started_at_unix_ms AS started_at_unix_ms, f.completed_at_unix_ms AS completed_at_unix_ms, f.truncated AS truncated, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.seed_ids AS seed_ids, f.seed_snapshot_json AS seed_snapshot_json, f.detector_version AS detector_version, f.hop_decay AS hop_decay, f.time_half_life_days AS time_half_life_days, f.max_paths_per_subject AS max_paths_per_subject, f.seed_count AS seed_count, f.path_count AS path_count, f.settings_json AS settings_json, f.error_message AS error_message, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_exposure_runs_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.run_id=p.publication_id AND f.revision=p.output_revision WHERE p.family='exposure' AND f.status='complete' AND f.truncated=0 AND f.source_revision=p.source_revision AND f.as_of_block=p.as_of_block;

CREATE OR REPLACE VIEW {{database}}.aml_exposure_paths_visible AS SELECT f.network_id AS network_id, f.path_id AS path_id, f.run_id AS run_id, f.subject_id AS subject_id, f.seed_id AS seed_id, f.direction AS direction, f.hop_count AS hop_count, f.asset_id AS asset_id, f.amount_raw AS amount_raw, f.amount_share AS amount_share, f.exposure_score AS exposure_score, f.attribution_method AS attribution_method, f.fund_continuity_claimed AS fund_continuity_claimed, f.path_subjects AS path_subjects, f.relationship_ids AS relationship_ids, f.tx_hashes AS tx_hashes, f.evidence_refs AS evidence_refs, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.seed_entity_id AS seed_entity_id, f.seed_category AS seed_category, f.seed_risk_level AS seed_risk_level, f.time_weight AS time_weight, f.service_mediated AS service_mediated, f.service_entity_id AS service_entity_id, f.continuity_type AS continuity_type, f.first_transfer_unix_ms AS first_transfer_unix_ms, f.last_transfer_unix_ms AS last_transfer_unix_ms, f.detector_version AS detector_version, f.allocation_json AS allocation_json, f.evidence_json AS evidence_json, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_exposure_paths_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.run_id=p.publication_id AND f.revision=p.output_revision INNER JOIN {{database}}.aml_exposure_runs_visible AS a ON f.network_id=a.network_id AND f.run_id=a.run_id AND f.revision=a.revision WHERE p.family='exposure';

CREATE OR REPLACE VIEW {{database}}.aml_address_exposures_visible AS SELECT f.network_id AS network_id, f.exposure_id AS exposure_id, f.run_id AS run_id, f.seed_id AS seed_id, f.source_subject_id AS source_subject_id, f.subject_id AS subject_id, f.hop_distance AS hop_distance, f.exposure_score AS exposure_score, f.path_count AS path_count, f.last_tx_hash AS last_tx_hash, f.last_seen_block AS last_seen_block, f.exposure_type AS exposure_type, f.best_path_amount_share AS best_path_amount_share, f.best_path_time_weight AS best_path_time_weight, f.service_mediated AS service_mediated, f.as_of_block AS as_of_block, f.source_revision AS source_revision, f.evidence_refs AS evidence_refs, f.raw_evidence_json AS raw_evidence_json, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms FROM {{database}}.aml_address_exposures_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.run_id=p.publication_id AND f.revision=p.output_revision INNER JOIN {{database}}.aml_exposure_runs_visible AS a ON f.network_id=a.network_id AND f.run_id=a.run_id AND f.revision=a.revision WHERE p.family='exposure' AND f.source_revision=p.source_revision AND f.as_of_block=p.as_of_block;

CREATE OR REPLACE VIEW {{database}}.aml_wallet_risk_assessments_visible AS SELECT f.network_id AS network_id, f.assessment_id AS assessment_id, f.subject_id AS subject_id, f.policy_version AS policy_version, f.risk_score AS risk_score, f.risk_level AS risk_level, f.probability_claimed AS probability_claimed, f.signal_count AS signal_count, f.exposure_run_id AS exposure_run_id, f.limitations AS limitations, f.as_of_block AS as_of_block, f.source_revision AS source_revision, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.top_reasons AS top_reasons, f.evidence_refs AS evidence_refs, f.as_of_unix_ms AS as_of_unix_ms, f.scoring_method AS scoring_method, f.evidence_json AS evidence_json, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_wallet_risk_assessments_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.assessment_id=p.publication_id AND f.revision=p.output_revision LEFT JOIN {{database}}.aml_exposure_runs_visible AS e ON f.network_id=e.network_id AND f.exposure_run_id=e.run_id WHERE p.family='risk' AND f.source_revision=p.source_revision AND f.as_of_block=p.as_of_block AND (isNull(f.exposure_run_id) OR e.run_id=ifNull(f.exposure_run_id,'') AND e.source_revision=f.source_revision);

CREATE OR REPLACE VIEW {{database}}.aml_wallet_risk_signals_visible AS SELECT f.network_id AS network_id, f.signal_id AS signal_id, f.assessment_id AS assessment_id, f.subject_id AS subject_id, f.policy_version AS policy_version, f.signal_type AS signal_type, f.contribution AS contribution, f.summary AS summary, f.evidence_refs AS evidence_refs, f.evidence_json AS evidence_json, f.as_of_block AS as_of_block, f.source_revision AS source_revision, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.signal_strength AS signal_strength, f.as_of_unix_ms AS as_of_unix_ms, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_wallet_risk_signals_current AS f INNER JOIN {{database}}.aml_analysis_publications_visible AS p ON f.network_id=p.network_id AND f.assessment_id=p.publication_id AND f.revision=p.output_revision INNER JOIN {{database}}.aml_wallet_risk_assessments_visible AS a ON f.network_id=a.network_id AND f.assessment_id=a.assessment_id AND f.revision=a.revision WHERE p.family='risk' AND f.source_revision=p.source_revision AND f.as_of_block=p.as_of_block;

CREATE OR REPLACE VIEW {{database}}.aml_asset_metadata_visible AS SELECT f.network_id AS network_id, f.asset_id AS asset_id, f.symbol AS symbol, f.name AS name, f.decimals AS decimals, f.asset_standard AS asset_standard, f.source_id AS source_id, f.source_reference AS source_reference, f.review_status AS review_status, f.reviewed_by AS reviewed_by, f.evidence_refs AS evidence_refs, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.total_supply_raw AS total_supply_raw, f.code_hash AS code_hash, f.is_verified AS is_verified, f.metadata_status AS metadata_status, f.observed_block AS observed_block, f.verified_at_unix_ms AS verified_at_unix_ms, f.reviewed_at_unix_ms AS reviewed_at_unix_ms, f.updated_at_unix_ms AS updated_at_unix_ms, f.raw_evidence_json AS raw_evidence_json, f.source_revision AS source_revision, f.observed_block_hash AS observed_block_hash FROM {{database}}.aml_asset_metadata_current AS f LEFT JOIN {{database}}.aml_sync_state_current AS s ON f.network_id=s.network_id LEFT JOIN {{database}}.aml_ingested_blocks_canonical AS b ON f.network_id=b.network_id AND f.observed_block=b.block_number AND f.observed_block_hash=b.block_hash WHERE (isNull(f.observed_block) AND isNull(f.source_revision) AND isNull(f.observed_block_hash)) OR (isNotNull(f.observed_block) AND isNotNull(f.observed_block_hash) AND f.source_revision=s.revision AND s.initialized=1 AND b.block_hash=ifNull(f.observed_block_hash,''));

CREATE OR REPLACE VIEW {{database}}.aml_metadata_jobs_visible AS SELECT f.network_id AS network_id, f.job_id AS job_id, f.asset_id AS asset_id, f.status AS status, f.attempts AS attempts, f.next_attempt_unix_ms AS next_attempt_unix_ms, f.last_error AS last_error, f.revision AS revision, f.created_at_unix_ms AS created_at_unix_ms, f.discovery_id AS discovery_id, f.discovered_block AS discovered_block, f.source_revision AS source_revision, f.last_error_class AS last_error_class, f.started_at_unix_ms AS started_at_unix_ms, f.completed_at_unix_ms AS completed_at_unix_ms, f.updated_at_unix_ms AS updated_at_unix_ms, f.raw_evidence_json AS raw_evidence_json FROM {{database}}.aml_metadata_jobs_current AS f LEFT JOIN {{database}}.aml_sync_state_current AS s ON f.network_id=s.network_id LEFT JOIN {{database}}.aml_metadata_discoveries_canonical AS d ON f.network_id=d.network_id AND f.discovery_id=d.discovery_id AND f.asset_id=d.asset_id AND f.discovered_block=d.block_number WHERE (isNull(f.discovery_id) AND isNull(f.discovered_block) AND isNull(f.source_revision)) OR (isNotNull(f.discovery_id) AND isNotNull(f.discovered_block) AND f.source_revision=s.revision AND s.initialized=1 AND d.discovery_id=ifNull(f.discovery_id,''));

